// A folded die-cut sticker: reflect the actual alpha mask across a moving diagonal crease.
// This keeps gaps in bicycle wheels, chair legs and foliage transparent while the paper bends.
function clippedPolygon(w,h,boundary,keepFlat) {
  const points=[{x:0,y:0},{x:w,y:0},{x:w,y:h},{x:0,y:h}];
  const score=p=>p.x/w+1-p.y/h-boundary;
  const result=[];
  for(let i=0;i<points.length;i++){
    const a=points[i],b=points[(i+1)%points.length],sa=score(a),sb=score(b);
    const insideA=keepFlat?sa<=0:sa>=0,insideB=keepFlat?sb<=0:sb>=0;
    if(insideA)result.push(a);
    if(insideA!==insideB){const t=sa/(sa-sb);result.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}
  }
  return result;
}
function clip(c,points){
  c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.clip();
}
export function makePaperBack(sprite){
  const back=document.createElement('canvas');back.width=sprite.width;back.height=sprite.height;
  const c=back.getContext('2d');c.drawImage(sprite,0,0);c.globalCompositeOperation='source-in';
  const shade=c.createLinearGradient(0,0,back.width,back.height);
  shade.addColorStop(0,'#fffcf3');shade.addColorStop(.48,'#f7f5eb');shade.addColorStop(.86,'#dedfd6');shade.addColorStop(1,'#bfc6bd');
  c.fillStyle=shade;c.fillRect(0,0,back.width,back.height);return back;
}
function leftPressGeometry(w,h,progress,bend=1){
  const p=Math.max(0,Math.min(1,progress)),smooth=p*p*(3-2*p);
  const flat=w*(.07+.93*smooth),remaining=w-flat;
  const angle=1.85*Math.pow(1-smooth,.7)*Math.max(0,Math.min(1,bend))+.03,radius=remaining/angle;
  return{p,flat,remaining,angle,radius,lift:Math.min(.72,h/(w*.9))};
}
export function pressedPaperPoint(u,v,w,h,progress,bend=1){
  const g=leftPressGeometry(w,h,progress,bend),px=u*w,py=v*h;
  if(g.p>.995||px<=g.flat)return{x:px-w/2,y:py-h/2};
  const distance=px-g.flat;
  return{x:g.flat+g.radius*Math.sin(distance/g.radius)-w/2,y:py-g.radius*(1-Math.cos(distance/g.radius))*g.lift-h/2};
}
function drawLeftSpread(c,sprite,back,w,h,progress,bend){
  const {p,flat,remaining,radius,lift}=leftPressGeometry(w,h,progress,bend);
  if(p>.995){c.drawImage(sprite,0,0,w,h);return;}
  // The left edge stays on the paper; the raised right side settles behind a moving crease.
  c.shadowColor='transparent';c.shadowBlur=0;c.shadowOffsetY=0;
  c.drawImage(sprite,0,0,flat/w*sprite.width,sprite.height,0,0,flat,h);
  const strips=40;
  for(let i=0;i<strips;i++){
    const d0=remaining*i/strips,d1=remaining*(i+1)/strips;
    const point=d=>({x:flat+radius*Math.sin(d/radius),y:-radius*(1-Math.cos(d/radius))*lift});
    const a=point(d0),b=point(d1);
    const sa=(flat+d0)/w*sprite.width,sb=(flat+d1)/w*sprite.width;
    const source=(d0+d1)/2/radius>Math.PI/2?back:sprite,sw=sb-sa;
    if(sw<=0)continue;
    c.save();
    c.transform((b.x-a.x)/sw,(b.y-a.y)/sw,0,h/source.height,a.x,a.y);
    // Overlap the texture samples slightly so antialiasing cannot leave hairline gaps between strips.
    const lo=Math.max(0,sa-1.2),hi=Math.min(source.width,sb+1.2);
    c.drawImage(source,lo,0,hi-lo,source.height,lo-sa,0,hi-lo,source.height);
    c.restore();
  }
}
export function drawCurledSticker(c,sprite,back,x,y,w,h,{curl=0,alpha=1,shadow=4,mode='diagonal',spread=0,bend=1}={}){
  if(w<=0||h<=0)return;
  c.save();c.translate(x-w/2,y-h/2);c.globalAlpha*=alpha;
  c.shadowColor='rgba(43,55,48,.26)';c.shadowBlur=shadow;c.shadowOffsetY=shadow*.5;
  if(mode==='left'){drawLeftSpread(c,sprite,back,w,h,spread,bend);c.restore();return;}
  if(curl<.006){c.drawImage(sprite,0,0,w,h);c.restore();return;}
  const amount=Math.max(0,Math.min(1,curl)),boundary=2-.91*amount;
  c.save();clip(c,clippedPolygon(w,h,boundary,true));c.drawImage(sprite,0,0,w,h);c.restore();
  // Reflection across x/w - y/h + 1 - boundary = 0. The slight compression reads as a rolled edge.
  const a=1/w,b=-1/h,d=1-boundary,n=a*a+b*b,k=1.87;
  c.save();c.transform(1-k*a*a/n,-k*a*b/n,-k*a*b/n,1-k*b*b/n,-k*a*d/n,-k*b*d/n);
  clip(c,clippedPolygon(w,h,boundary,false));
  c.shadowColor='rgba(47,56,51,.32)';c.shadowBlur=Math.max(2,shadow*.65);c.shadowOffsetY=1.5;
  c.drawImage(back,0,0,w,h);c.restore();c.restore();
}
export function drawGoldSpark(c,x,y,r,alpha=1){
  c.save();c.globalAlpha*=alpha;c.translate(x,y);c.shadowColor='#ffdf73';c.shadowBlur=7;
  const g=c.createLinearGradient(-r,-r,r,r);g.addColorStop(0,'#fff2a2');g.addColorStop(.5,'#f2c64b');g.addColorStop(1,'#cb9730');c.fillStyle=g;
  c.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;const px=Math.cos(a)*rr,py=Math.sin(a)*rr;i?c.lineTo(px,py):c.moveTo(px,py);}c.closePath();c.fill();c.restore();
}

/**
 * A printed, blue-grey metal precision tweezer, about 220 CSS px long.
 * (tipX, tipY) is the midpoint of its two actual jaws. angle=0 points the tail
 * toward negative Y; open=0..1 spreads the jaws while their folded tail stays fixed.
 */
export function drawTweezers(ctx, tipX, tipY, { angle = -0.48, scale = 1, open = 0, opacity = 1 } = {}) {
  if (!ctx || !Number.isFinite(tipX) || !Number.isFinite(tipY)) return;
  if (!Number.isFinite(angle) || !Number.isFinite(scale) || scale <= 0 || !Number.isFinite(opacity)) return;
  const alpha = Math.max(0, Math.min(1, opacity));
  const opening = Math.max(0, Math.min(1, Number.isFinite(open) ? open : 0));
  if (!alpha) return;

  const shiftFor = (y, jaw, rear = false) => {
    const t = Math.max(0, Math.min(1, (y + 220) / 220));
    return jaw * Math.pow(t, 1.35) - (rear ? 0.9 * Math.sin(t * Math.PI) : 0);
  };
  const handlePath = (c, shift) => {
    const p = (x, y) => [x + shift(y), y];
    c.beginPath();
    c.moveTo(...p(-10.2, -208));
    c.bezierCurveTo(...p(-10.2, -219), ...p(10.2, -219), ...p(10.2, -208));
    c.bezierCurveTo(...p(11.5, -169), ...p(10.6, -95), ...p(7.5, -50));
    c.lineTo(...p(-7.4, -50));
    c.bezierCurveTo(...p(-9.3, -89), ...p(-11.5, -169), ...p(-10.2, -208));
    c.closePath();
  };
  const bladePath = (c, shift) => {
    const p = (x, y) => [x + shift(y), y];
    c.beginPath();
