  };
  const leaf = (c, x, y, length, turn) => {
    c.save(); c.translate(x, y); c.rotate(turn);
    c.beginPath(); c.moveTo(0, 0);
    c.bezierCurveTo(-length * 0.28, -length * 0.45, -length * 0.14, -length * 0.86, 0, -length);
