type Hit = Rect & { id: string; action: () => void; disabled?: boolean };
type Paste = { ticket: any; sticker: any; start: number; from: Point; to: Point };
const ease = (p: number) => { p = Math.max(0, Math.min(1, p)); return p * p * (3 - 2 * p); };
const lerp = (a: number, b: number, p: number) => a + (b - a) * p;
const contains = (r: Rect, x: number, y: number) => x >= r.x && y >= r.y && x <= r.x + r.width && y <= r.y + r.height;

/** Canvas renderer shared by the real WeChat entry and a separate diagnostic host.
 * It never reads DOM, window, browser storage, CSS, or the device's filesystem.
 * Native App uses the Sprite-based Cocos adapter with this same layout/session.
 */
export class CanvasGame {
  readonly canvas: any;
  readonly platform: GamePlatform;
  layout: any;
  session: GameSession;
  private context: any;
  private images = new Map<string, any>();
  private loading = new Map<string, Promise<any>>();
  private alphas = new Map<string, { pixels: Uint8ClampedArray; width: number; height: number }>();
  private backs = new Map<string, any>();
  private silhouettes = new Map<string, any>();
  private width = 390;
  private height = 844;
  private ratio = 1;
  private safe = { left: 0, top: 0, right: 390, bottom: 844 };
  private sceneRect: Rect = { x: 16, y: 126, width: 358, height: 468 };
  private camera: Camera = { x: 270, y: 210, scale: 0.6 };
  private hits: Hit[] = [];
  private dirty = true;
  private running = false;
  private frame: any = null;
  private pointer: { id: number; start: Point; at: Point; moved: boolean; button?: Hit } | null = null;
  private heldAt: Point | null = null;
  private paste: Paste | null = null;
  private burst: { start: number; at: Point; final: boolean } | null = null;
  private tour: { start: number; from: Camera; to: Camera; overview: Camera } | null = null;
  private overview = false;
  private page = 0;
  private editor = false;
  private draft: any = null;
  private editId: string | null = null;
  private editUndo: any[] = [];
  private editRedo: any[] = [];
  private editDragStart: Point | null = null;
  private loaded = false;
  private status = '准备剧院素材…';
  private unsubscribe: (() => void) | null = null;

  constructor(options: { canvas: any; layout: any; platform: GamePlatform }) {
    this.canvas = options.canvas;
    this.context = this.canvas.getContext('2d');
    this.platform = options.platform;
    this.layout = JSON.parse(JSON.stringify(options.layout));
    this.session = new GameSession(this.layout);
  }

  async start(): Promise<void> {
    const edited = this.platform.storage.get(this.layoutKey());
    if (edited && validateLayout(edited).length === 0 && edited.sceneId === this.layout.sceneId) this.layout = edited;
    this.bindSession();
    const save = this.platform.storage.get(this.saveKey());
    if (save) {
      const result = this.session.restore(save);
      if (!result.ok) this.platform.toast?.('排布版本已更新，已保留旧记录并从本关开始。');
    }
    this.resize(this.width, this.height, this.ratio, this.safe);
    this.running = true;
    this.tick();
    await Promise.all([this.image(this.layout.scene.baseAssetKey), ...this.layout.fixedLayers.map((f: any) => this.image(f.assetKey))]);
    await this.loadCurrentAndNext();
    this.loaded = true;
    this.status = '拿起贴纸，寻找它在剧院里的位置';
    this.camera = this.cameraForCurrent();
    if (this.session.getSnapshot().phase === 'transitioning') this.startTour();
    this.dirty = true;
  }

  private bindSession(): void {
    this.unsubscribe?.();
    this.session = new GameSession(this.layout);
    this.unsubscribe = this.session.subscribe((snapshot, event) => {
      if (event.type !== 'selected' && event.type !== 'selection-cancelled') this.persist();
      if (event.type === 'transition-finished' || event.type === 'undo') {
        this.page = 0;
        this.loadCurrentAndNext().catch(() => this.platform.toast?.('素材读取失败，请重试。'));
      }
      this.dirty = true;
    });
  }

  resize(width: number, height: number, ratio = 1, safeArea?: any): void {
    this.width = Math.max(240, width); this.height = Math.max(400, height); this.ratio = Math.max(1, ratio);
    this.safe = safeArea || { left: 0, top: 0, right: width, bottom: height };
    this.canvas.width = Math.round(this.width * this.ratio); this.canvas.height = Math.round(this.height * this.ratio);
    const top = Math.max(12, this.safe.top || 0);
    const bottom = Math.max(10, this.height - (this.safe.bottom || this.height));
    const contentWidth = Math.min(760, this.width - 32);
    this.sceneRect = { x: (this.width - contentWidth) / 2, y: top + 116, width: contentWidth, height: Math.max(190, this.height - top - bottom - 325) };
    this.camera = this.editor || this.overview ? this.cameraForOverview() : this.cameraForCurrent();
    this.dirty = true;
  }

  private saveKey() { return `theatre:progress:${this.layout.sceneId}:${this.layout.layoutRevision}`; }
  private layoutKey() { return `theatre:layout:${this.layout.sceneId}`; }
  private persist(): void { this.platform.storage.set(this.saveKey(), this.session.exportSave()); }
  private async image(key: string): Promise<any> {
    if (this.images.has(key)) return this.images.get(key);
    if (this.loading.has(key)) return this.loading.get(key);
    const pending = this.platform.loadImage(key).then(image => {
      this.images.set(key, image); this.loading.delete(key); this.dirty = true; return image;
    }).catch(error => { this.loading.delete(key); throw error; });
    this.loading.set(key, pending); return pending;
  }

  private async loadCurrentAndNext(): Promise<void> {
    const state = this.session.getSnapshot();
    const blocks = this.layout.geoBlocks.slice().sort((a: any, b: any) => a.blockOrder - b.blockOrder);
    const index = Math.max(0, blocks.findIndex((b: any) => b.blockId === state.activeBlockId));
    const selected = new Set([blocks[index]?.blockId, blocks[index + 1]?.blockId]);
    const ready = this.layout.stickers.filter((s: any) => selected.has(s.geoBlock) || state.placedStickerIds.includes(s.stickerId));
    const keys = new Set<string>();
    for (const s of ready) { keys.add(s.assetKey); for (const p of s.renderParts) keys.add(p.assetKey); }
    await Promise.all(Array.from(keys).map(key => this.image(key)));
  }

  private cameraForBounds(bounds: Rect): Camera {
    return { x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height / 2, scale: Math.min(this.sceneRect.width / bounds.width, this.sceneRect.height / bounds.height) };
  }
  private cameraForOverview(): Camera { return this.cameraForBounds({ x: 0, y: 0, width: this.layout.scene.width, height: this.layout.scene.height }); }
  private cameraForCurrent(): Camera {
    const state = this.session.getSnapshot();
    const block = this.layout.geoBlocks.find((b: any) => b.blockId === state.activeBlockId);
    return !block || state.phase === 'completed' ? this.cameraForOverview() : this.cameraForBounds(block.cameraBounds || block.bounds);
  }
  private screen(point: Point): Point { return { x: this.sceneRect.x + this.sceneRect.width / 2 + (point.x - this.camera.x) * this.camera.scale, y: this.sceneRect.y + this.sceneRect.height / 2 + (point.y - this.camera.y) * this.camera.scale }; }
  private world(point: Point): Point { return { x: this.camera.x + (point.x - this.sceneRect.x - this.sceneRect.width / 2) / this.camera.scale, y: this.camera.y + (point.y - this.sceneRect.y - this.sceneRect.height / 2) / this.camera.scale }; }
  private sticker(id: string, layout = this.editor ? this.draft : this.layout): any { return layout.stickers.find((s: any) => s.stickerId === id); }
  private center(s: any): Point {
    const a = (s.rotation || 0) * Math.PI / 180;
    const x = (0.5 - s.anchor.x) * s.sourceSize.width * s.scale;
    const y = (0.5 - s.anchor.y) * s.sourceSize.height * s.scale;
    return { x: s.position.x + x * Math.cos(a) - y * Math.sin(a), y: s.position.y + x * Math.sin(a) + y * Math.cos(a) };
  }

  private hitSticker(s: any, point: Point): boolean {
    const w = this.world(point); const dx = w.x - s.position.x, dy = w.y - s.position.y;
    const a = -(s.rotation || 0) * Math.PI / 180;
    const x = (dx * Math.cos(a) - dy * Math.sin(a)) / s.scale + s.anchor.x * s.sourceSize.width;
    const y = (dx * Math.sin(a) + dy * Math.cos(a)) / s.scale + s.anchor.y * s.sourceSize.height;
    if (x < 0 || y < 0 || x >= s.sourceSize.width || y >= s.sourceSize.height) return false;
    const alpha = this.alpha(s);
    if (!alpha) return true;
    return alpha.pixels[(Math.floor(y) * alpha.width + Math.floor(x)) * 4 + 3] > 18;
  }
  private alpha(s: any): any {
    if (this.alphas.has(s.assetKey)) return this.alphas.get(s.assetKey);
    const image = this.images.get(s.assetKey); if (!image) return null;
    const canvas = this.platform.createCanvas(s.sourceSize.width, s.sourceSize.height), c = canvas.getContext('2d');
    c.drawImage(image, 0, 0, s.sourceSize.width, s.sourceSize.height);
    const alpha = { pixels: c.getImageData(0, 0, canvas.width, canvas.height).data, width: canvas.width, height: canvas.height };
    this.alphas.set(s.assetKey, alpha); return alpha;
  }
  private paperBack(s: any): any {
    if (!this.backs.has(s.assetKey)) this.backs.set(s.assetKey, makePaperBack(this.images.get(s.assetKey), (w: number, h: number) => this.platform.createCanvas(w, h)));
    return this.backs.get(s.assetKey);
  }
  private silhouette(s: any): any {
    if (this.silhouettes.has(s.assetKey)) return this.silhouettes.get(s.assetKey);
    const image = this.images.get(s.assetKey), canvas = this.platform.createCanvas(image.width, image.height), c = canvas.getContext('2d');
    c.drawImage(image, 0, 0); c.globalCompositeOperation = 'source-in'; c.fillStyle = '#513b34'; c.fillRect(0, 0, canvas.width, canvas.height);
    this.silhouettes.set(s.assetKey, canvas); return canvas;
  }

  pointerDown(x: number, y: number, id = 0): void {
    if (!this.loaded || this.pointer || this.paste || this.tour || this.burst) return;
    const button = this.hits.slice().reverse().find(h => contains(h, x, y));
    if (button?.disabled) return;
    this.pointer = { id, start: { x, y }, at: { x, y }, moved: false, button };
    if (button?.id.startsWith('sticker:')) {
      const sid = button.id.slice(8); button.action();
      if (!this.editor && this.session.getSnapshot().selectedStickerId) this.heldAt = { x, y: y - 62 };
      return;
    }
    if (this.editor && contains(this.sceneRect, x, y)) {
      const ordered = this.draft.stickers.slice().sort((a: any, b: any) => b.placementOrder - a.placementOrder);
      const found = ordered.find((s: any) => this.hitSticker(s, { x, y }));
      if (found) { this.editId = found.stickerId; this.editDragStart = { ...found.position }; this.pushEditUndo(); }
      this.dirty = true;
    }
  }
  pointerMove(x: number, y: number, id = 0): void {
    if (!this.pointer || this.pointer.id !== id) return;
    this.pointer.at = { x, y };
    if (Math.hypot(x - this.pointer.start.x, y - this.pointer.start.y) > 7) this.pointer.moved = true;
    if (this.editor && this.editId && this.editDragStart && !this.pointer.button) {
      const delta = { x: (x - this.pointer.start.x) / this.camera.scale, y: (y - this.pointer.start.y) / this.camera.scale };
      this.draft = patchStickerDraft(this.draft, this.editId, { position: { x: this.editDragStart.x + delta.x, y: this.editDragStart.y + delta.y } });
    } else if (this.session.getSnapshot().selectedStickerId && this.pointer.moved) this.heldAt = { x, y: y - 62 };
