    if (!sid) return;
    if (pointer.button?.id.startsWith('sticker:') && !pointer.moved) { this.heldAt = null; this.dirty = true; return; }
    const s = this.sticker(sid); const target = this.screen(this.center(s));
    const held = this.heldAt || { x, y };
    const close = Math.hypot(held.x - target.x, held.y - target.y) <= Math.max(32, Math.min(70, Math.max(s.sourceSize.width, s.sourceSize.height) * s.scale * this.camera.scale * .28));
    if (contains(this.sceneRect, x, y) && (this.hitSticker(s, { x, y }) || (pointer.moved && close))) this.place(s, held);
