  }
  private startTour(): void {
    const current = this.session.getSnapshot().activeBlockId;
    const blocks = this.layout.geoBlocks.slice().sort((a: any, b: any) => a.blockOrder - b.blockOrder);
    const next = blocks[blocks.findIndex((b: any) => b.blockId === current) + 1];
    this.tour = { start: this.platform.now(), from: { ...this.camera }, overview: this.cameraForOverview(), to: next ? this.cameraForBounds(next.cameraBounds || next.bounds) : this.cameraForOverview() };
    this.status = '这一角完成了，看看整座剧院'; this.dirty = true;
  }
  private tick = (): void => {
    if (!this.running) return;
    const now = this.platform.now();
    if (this.paste && now - this.paste.start >= 1550) {
      const paste = this.paste; this.paste = null;
      if (this.session.commitPlacement(paste.ticket)) {
        const state = this.session.getSnapshot();
        this.burst = { start: now, at: paste.to, final: state.phase === 'transitioning' || state.phase === 'completed' };
        this.page = 0; this.status = state.phase === 'completed' ? '剧院幕后，已经完整呈现' : '贴好了，给这一角一点星光';
      }
      this.dirty = true;
    }
    if (this.burst && now - this.burst.start >= 1350) {
      this.burst = null;
      if (this.session.getSnapshot().phase === 'transitioning') this.startTour();
      else { this.status = '拿起下一张，继续还原这一角'; this.dirty = true; }
    }
