      else if (t < 1150) { from = to = this.tour.overview; p = 1; }
      else { from = this.tour.overview; to = this.tour.to; p = ease((t - 1150) / 800); }
      this.camera = { x: lerp(from.x, to.x, p), y: lerp(from.y, to.y, p), scale: lerp(from.scale, to.scale, p) };
