import { CanvasGame } from '../../rendering/CanvasGame';

declare const wx: any;
declare function requestAnimationFrame(callback: (time: number) => void): number;
declare function cancelAnimationFrame(id: number): void;

export interface AssetSubpackage { prefix: string; name: string }
export interface WechatOptions {
  api?: any;
  assetSubpackages?: AssetSubpackage[];
  preloadSubpackages?: string[];
}
const DEFAULT_PACKAGES: AssetSubpackage[] = ['base', 'reference', 'assets', 'parts', 'fixed']
  .map(folder => ({ prefix: `resources/${folder}/`, name: `theatre-${folder}` }));

/** Host API only; game state, world coordinates and drawing stay in shared code. */
export async function startWechatGame(layout: any, options: WechatOptions = {}) {
  const api = options.api || wx;
  // The FIRST wx.createCanvas is on-screen. Later canvases are off-screen.
  const canvas = api.createCanvas();
  const packages = options.assetSubpackages || DEFAULT_PACKAGES;
  const loads = new Map<string, Promise<void>>();
  const images = new Map<string, Promise<any>>();
  const performanceClock = api.getPerformance ? api.getPerformance() : null;
  // Official Mini Game Performance.now is MICROseconds, not browser milliseconds.
  const now = () => performanceClock ? performanceClock.now() / 1000 : Date.now();
  const toast = (message: string) => api.showToast({ title: String(message), icon: 'none', duration: 2800 });
  const loadPackage = (name: string): Promise<void> => {
    if (!loads.has(name)) {
      const pending = new Promise<void>((resolve, reject) => {
        if (!api.loadSubpackage) { reject(new Error('当前微信版本不支持素材分包，请更新微信')); return; }
        api.loadSubpackage({ name, success: () => resolve(), fail: reject });
      }).catch(error => { loads.delete(name); throw error; });
      loads.set(name, pending);
    }
    return loads.get(name)!;
  };
  const importJson = (): Promise<string | null> => new Promise((resolve, reject) => {
    api.getClipboardData({ success: (result: any) => {
      const text = String(result.data || '').trim();
      if (!text) { toast('请先复制排布 JSON，再点导入'); resolve(null); } else resolve(text);
    }, fail: reject });
  });
  const platform = {
    createCanvas(width: number, height: number) {
      const offscreen = api.createCanvas();
      offscreen.width = Math.max(1, Math.ceil(width)); offscreen.height = Math.max(1, Math.ceil(height));
      return offscreen;
    },
    loadImage(assetKey: string): Promise<any> {
      if (!images.has(assetKey)) {
        const bundle = packages.find(pack => assetKey.startsWith(pack.prefix));
        const ready = bundle ? loadPackage(bundle.name) : Promise.resolve();
        images.set(assetKey, ready.then(() => new Promise((resolve, reject) => {
          const image = api.createImage();
          image.onload = () => resolve(image);
          image.onerror = (error: any) => reject(new Error(`无法读取素材 ${assetKey}: ${error?.errMsg || 'image error'}`));
          image.src = assetKey;
        })).catch(error => { images.delete(assetKey); throw error; }));
      }
      return images.get(assetKey)!;
    },
    storage: {
      get(key: string) { const value = api.getStorageSync(key); return value === '' || value === undefined ? null : value; },
      set(key: string, value: any) { api.setStorageSync(key, value); },
      remove(key: string) { api.removeStorageSync(key); },
    },
    now,
    requestFrame(callback: (time: number) => void) { return requestAnimationFrame(() => callback(now())); },
    cancelFrame(id: number) { cancelAnimationFrame(id); },
    toast,
    confirm(message: string): Promise<boolean> {
      return new Promise((resolve, reject) => api.showModal({ title: '确认操作', content: message,
        confirmText: '确认', cancelText: '取消', success: (result: any) => resolve(!!result.confirm), fail: reject }));
    },
    importJson, chooseJson: importJson,
    async exportJson(text: string): Promise<void> {
      const filePath = `${api.env.USER_DATA_PATH}/theatre-layout-user.json`;
      api.getFileSystemManager().writeFileSync(filePath, text, 'utf8');
      await new Promise<void>((resolve, reject) => api.setClipboardData({ data: text,
