export function patchStickerDraft(layout: GameLayout, stickerId: string, patch: StickerDraftPatch): GameLayout {
  const draft = createLayoutDraft(layout);
  const sticker = draft.stickers.find(entry => entry.stickerId === stickerId);
  if (!sticker) throw new Error(`Unknown sticker ${stickerId}`);
  const allowed = new Set(['position', 'scale', 'rotation', 'areaLevel', 'geoBlock', 'layerIndex', 'anchor']);
  for (const key of Object.keys(patch)) {
    if (!allowed.has(key)) throw new Error(`Unsupported editable sticker field ${key}`);
    (sticker as Record<string, unknown>)[key] = clone((patch as Record<string, unknown>)[key]);
  }
  assertLayout(draft);
  refreshPlayMetadata(draft);
  return draft;
}

/**
