 * In a multipart scene, retain each owner's relative part-layer differences and
 * include fixed foreground in the same global queue; never collapse a person into
 * one contiguous layer. For an exact custom queue use reorderRenderPartsDraft.
 */
export function reorderDraft(layout: GameLayout, orderedStickerIds?: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (draft.renderOrder?.length) {
    if (orderedStickerIds) {
      throw new Error('Multipart scenes require an explicit render-part queue; use reorderRenderPartsDraft');
    }
    const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
    for (const entry of draft.renderOrder) {
      if (entry.kind !== 'stickerPart') continue;
      const sticker = stickers.get(entry.stickerId ?? '');
      const parts = sticker?.renderParts;
      const part = parts?.find(candidate => candidate.partId === entry.partId);
      if (!sticker || !parts?.length || !part) throw new Error(`Invalid render queue part ${entry.partId}`);
      const sourceLayer = Math.min(...parts.map(candidate => candidate.layerIndex));
      entry.layerIndex = sticker.layerIndex + part.layerIndex - sourceLayer;
    }
    draft.renderOrder.sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder);
    synchronizeRenderOrders(draft);
    refreshPlayMetadata(draft);
    assertLayout(draft);
