    let left = bounds.x, top = bounds.y, right = left + bounds.width, bottom = top + bounds.height;
    for (const s of this.layout.stickers.filter((s: any) => s.geoBlock === block.blockId)) {
      const a = s.rotation * Math.PI / 180;
      for (const part of s.renderParts) for (const corner of [[0, 0], [part.sourceSize.width, 0], [0, part.sourceSize.height], [part.sourceSize.width, part.sourceSize.height]]) {
        const x = (part.offset.x + corner[0] - s.anchor.x * s.sourceSize.width) * s.scale;
        const y = (part.offset.y + corner[1] - s.anchor.y * s.sourceSize.height) * s.scale;
        const wx = s.position.x + x * Math.cos(a) - y * Math.sin(a), wy = s.position.y + x * Math.sin(a) + y * Math.cos(a);
        const padding = block.cameraPadding || 24;
        left = Math.min(left, wx - padding); right = Math.max(right, wx + padding); top = Math.min(top, wy - padding); bottom = Math.max(bottom, wy + padding);
