  }
  private screen(point: Point): Point { return { x: this.sceneRect.x + this.sceneRect.width / 2 + (point.x - this.camera.x) * this.camera.scale, y: this.sceneRect.y + this.sceneRect.height / 2 + (point.y - this.camera.y) * this.camera.scale }; }
  private world(point: Point): Point { return { x: this.camera.x + (point.x - this.sceneRect.x - this.sceneRect.width / 2) / this.camera.scale, y: this.camera.y + (point.y - this.sceneRect.y - this.sceneRect.height / 2) / this.camera.scale }; }
  private sticker(id: string, layout = this.editor ? this.draft : this.layout): any { return layout.stickers.find((s: any) => s.stickerId === id); }
  private center(s: any): Point {
    const a = (s.rotation || 0) * Math.PI / 180;
    const x = (0.5 - s.anchor.x) * s.sourceSize.width * s.scale;
    const y = (0.5 - s.anchor.y) * s.sourceSize.height * s.scale;
    return { x: s.position.x + x * Math.cos(a) - y * Math.sin(a), y: s.position.y + x * Math.sin(a) + y * Math.cos(a) };
  }

  private hitSticker(s: any, point: Point): boolean {
    const w = this.world(point); const dx = w.x - s.position.x, dy = w.y - s.position.y;
    const a = -(s.rotation || 0) * Math.PI / 180;
    const x = (dx * Math.cos(a) - dy * Math.sin(a)) / s.scale + s.anchor.x * s.sourceSize.width;
