  private skipEmptyBlocks(start: number): number {
    let index = start;
    while (index < this.blocks.length && this.blockStickers.get(this.blocks[index].blockId)!.length === 0) index++;
    return index;
  }

  private activeLevel(blockIndex: number, placed: Set<string>): AreaLevel | null {
    const members = this.blockStickers.get(this.blocks[blockIndex]?.blockId ?? '') ?? [];
    return AREA_LEVELS.find(level => members.some(sticker => sticker.areaLevel === level && !placed.has(sticker.stickerId))) ?? null;
  }

  private readyIds(): string[] {
    const level = this.activeLevel(this.blockIndex, this.placed);
    return (this.blockStickers.get(this.blocks[this.blockIndex]?.blockId ?? '') ?? [])
      .filter(sticker => sticker.areaLevel === level && !this.placed.has(sticker.stickerId)
        && (sticker.dependsOn ?? []).every(id => this.placed.has(id)))
      .map(sticker => sticker.stickerId);
  }

  private matchesTicket(ticket: PlacementTicket): boolean {
    return record(ticket) && !!this.pending && ticket.stickerId === this.pending.stickerId
      && ticket.transactionId === this.pending.transactionId;
  }

  private replay(history: string[]): ReplayedHistory {
    const placed = new Set<string>();
    let nextBlockIndex = this.skipEmptyBlocks(0);
    let lastCompletedBlockIndex: number | null = null;
    const errors: string[] = [];
    for (const [index, id] of history.entries()) {
      const sticker = this.stickers.get(id);
      if (!sticker) { errors.push(`history[${index}] has unknown sticker ${id}`); break; }
      if (placed.has(id)) { errors.push(`history[${index}] repeats sticker ${id}`); break; }
      if (sticker.geoBlock !== this.blocks[nextBlockIndex]?.blockId) {
        errors.push(`history[${index}] enters a block before the previous block is complete`); break;
      }
      if (sticker.areaLevel !== this.activeLevel(nextBlockIndex, placed)) {
        errors.push(`history[${index}] violates L1/L2/L3 stage order`); break;
      }
      if (!(sticker.dependsOn ?? []).every(dependency => placed.has(dependency))) {
        errors.push(`history[${index}] violates sticker dependencies`); break;
      }
      placed.add(id);
      lastCompletedBlockIndex = null;
      if (this.activeLevel(nextBlockIndex, placed) === null) {
        lastCompletedBlockIndex = nextBlockIndex;
        nextBlockIndex = this.skipEmptyBlocks(nextBlockIndex + 1);
      }
    }
    return { placed, nextBlockIndex, lastCompletedBlockIndex, errors };
  }

  private emit(event: Omit<SessionEvent, 'revision'>): void {
    this.revision++;
    const completeEvent: SessionEvent = { ...event, revision: this.revision };
    // Capture once before listeners: a listener may synchronously perform another action.
    const snapshot = this.getSnapshot();
    for (const listener of [...this.listeners]) listener(clone(snapshot), { ...completeEvent });
  }
}

export type StickerDraftPatch = Partial<Pick<StickerPlacement,
  'position' | 'scale' | 'rotation' | 'areaLevel' | 'geoBlock' | 'layerIndex' | 'anchor'>>;

/** Pure JSON draft helpers. They never load, cut, transform or write raster files. */
export function createLayoutDraft(layout: GameLayout): GameLayout {
  assertLayout(layout);
  return clone(layout);
}

export function patchStickerDraft(layout: GameLayout, stickerId: string, patch: StickerDraftPatch): GameLayout {
  const draft = createLayoutDraft(layout);
  const sticker = draft.stickers.find(entry => entry.stickerId === stickerId);
  if (!sticker) throw new Error(`Unknown sticker ${stickerId}`);
  const allowed = new Set(['position', 'scale', 'rotation', 'areaLevel', 'geoBlock', 'layerIndex', 'anchor']);
  for (const key of Object.keys(patch)) {
    if (!allowed.has(key)) throw new Error(`Unsupported editable sticker field ${key}`);
    (sticker as Record<string, unknown>)[key] = clone((patch as Record<string, unknown>)[key]);
  }
  assertLayout(draft);
  refreshPlayMetadata(draft);
  return draft;
}

/**
 * Explicit reorder only. Omitting IDs sorts coarse layerIndex, then existing order.
 * In a multipart scene, retain each owner's relative part-layer differences and
 * include fixed foreground in the same global queue; never collapse a person into
 * one contiguous layer. For an exact custom queue use reorderRenderPartsDraft.
 */
export function reorderDraft(layout: GameLayout, orderedStickerIds?: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (draft.renderOrder?.length) {
    if (orderedStickerIds) {
      throw new Error('Multipart scenes require an explicit render-part queue; use reorderRenderPartsDraft');
    }
    const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
    for (const entry of draft.renderOrder) {
      if (entry.kind !== 'stickerPart') continue;
      const sticker = stickers.get(entry.stickerId ?? '');
      const parts = sticker?.renderParts;
      const part = parts?.find(candidate => candidate.partId === entry.partId);
      if (!sticker || !parts?.length || !part) throw new Error(`Invalid render queue part ${entry.partId}`);
      const sourceLayer = Math.min(...parts.map(candidate => candidate.layerIndex));
      entry.layerIndex = sticker.layerIndex + part.layerIndex - sourceLayer;
    }
    draft.renderOrder.sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder);
    synchronizeRenderOrders(draft);
    refreshPlayMetadata(draft);
    assertLayout(draft);
    return draft;
  }
  const ids = orderedStickerIds ? [...orderedStickerIds]
    : [...draft.stickers].sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder)
      .map(sticker => sticker.stickerId);
  const known = new Set(draft.stickers.map(sticker => sticker.stickerId));
  if (ids.length !== known.size || new Set(ids).size !== known.size || ids.some(id => !known.has(id))) {
    throw new Error('Reorder must include every sticker ID exactly once');
  }
  const rank = new Map(ids.map((id, index) => [id, (index + 1) * 10]));
  for (const sticker of draft.stickers) sticker.placementOrder = rank.get(sticker.stickerId)!;
  refreshPlayMetadata(draft);
  assertLayout(draft);
  return draft;
}

/** Stable identity for an entry in the single global part/fixed painter queue. */
export function renderEntryKey(entry: RenderQueueEntry): string {
  return entry.kind === 'fixed' ? `fixed:${entry.fixedId}` : `stickerPart:${entry.partId}`;
}

export function reorderRenderPartsDraft(layout: GameLayout, orderedEntryKeys: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (!draft.renderOrder) throw new Error('Layout has no render-part queue');
  const entries = new Map(draft.renderOrder.map(entry => [renderEntryKey(entry), entry]));
  if (entries.size !== draft.renderOrder.length || orderedEntryKeys.length !== entries.size
    || new Set(orderedEntryKeys).size !== entries.size || orderedEntryKeys.some(key => !entries.has(key))) {
    throw new Error('Render-part reorder must include every part/fixed entry exactly once');
  }
  draft.renderOrder = orderedEntryKeys.map(key => entries.get(key)!);
  synchronizeRenderOrders(draft);
  refreshPlayMetadata(draft);
  assertLayout(draft);
  return draft;
}

function synchronizeRenderOrders(draft: GameLayout): void {
  const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
  const fixed = new Map((draft.fixedLayers ?? []).map(layer => [layer.fixedId, layer]));
  for (const [index, entry] of (draft.renderOrder ?? []).entries()) {
    entry.placementOrder = (index + 1) * 10;
    entry.paintOrder = entry.placementOrder;
    if (entry.kind === 'fixed') {
      const layer = fixed.get(entry.fixedId ?? '');
      if (!layer) throw new Error(`Unknown fixed render layer ${entry.fixedId}`);
      layer.placementOrder = entry.placementOrder;
      layer.paintOrder = entry.placementOrder;
      layer.layerIndex = entry.layerIndex;
    } else {
      const part = stickers.get(entry.stickerId ?? '')?.renderParts?.find(candidate => candidate.partId === entry.partId);
      if (!part) throw new Error(`Unknown render part ${entry.partId}`);
      part.placementOrder = entry.placementOrder;
      part.paintOrder = entry.placementOrder;
      part.layerIndex = entry.layerIndex;
    }
  }
  for (const sticker of draft.stickers) {
    if (sticker.renderParts?.length) sticker.placementOrder = Math.min(...sticker.renderParts.map(part => part.placementOrder));
  }
}

